/**
 * Click LINE Account login button
 * Returns: {clicked: true} or {error: string}
 */
function() {
  const btn = document.querySelector('button:has(i18n-message[key="login.button.loginWithLine"])');
  if (btn) {
    btn.click();
    return { clicked: true };
  }
  return { error: 'LINE Account button not found' };
}

/**
 * Click Login button on LINE OAuth page
 * Handles both email/password page and quick-login page (with user avatar)
 * Returns: {clicked: true} or {error: string}
 */
function() {
  // Try multiple selectors to handle different page layouts:
  // 1. Email/password page: .mdFormGroup01Btn button.MdBtn01[type="submit"]
  // 2. Quick-login page: button with text "登入"
  // 3. Fallback: any submit button with MdBtn01 class

  const selectors = [
    '.mdFormGroup01Btn button.MdBtn01[type="submit"]',
    'button.MdBtn01[type="submit"]',
    'button[type="submit"]'
  ];

  for (const selector of selectors) {
    const btn = document.querySelector(selector);
    if (btn && btn.textContent.includes('登入')) {
      btn.click();
      return { clicked: true, selector };
    }
  }

  return { error: 'Login button not found', tried: selectors };
}

/**
 * List all chat items from LINE OA chat list with unread status.
 * Run via browser evaluate on chat.line.biz (chat list page).
 *
 * Returns: [{ name, time, lastMsg, unread }]
 * - name: customer display name
 * - time: last message time (e.g., "11:56", "Monday", "2/10")
 * - lastMsg: preview of last message (up to 100 chars)
 * - unread: true if green dot (span.badge.badge-pin) is visible
 *
 * ONE-LINER version (copy this for browser evaluate fn parameter):
 * (function(){var r=document.querySelectorAll('.list-group-item-chat');return Array.from(r).map(function(e){var h=e.querySelector('h6');var p=e.querySelector('.text-muted.small');var pt=p?p.textContent.trim():'';var ms=e.querySelectorAll('.text-muted');var t='';for(var i=0;i<ms.length;i++){var v=ms[i].textContent.trim();if(v&&v.length<20&&v!==pt)t=v;}var d=e.querySelector('span.badge.badge-pin');var u=!!d&&getComputedStyle(d).display!=='none';return{name:h?h.textContent.trim():'',time:t,lastMsg:pt.substring(0,100),unread:u};}).filter(function(i){return i.name;});})()
 */
function() {
  const items = document.querySelectorAll('.list-group-item-chat');
  return Array.from(items).map(el => {
    const h6 = el.querySelector('h6');
    const preview = el.querySelector('.text-muted.small');
    const prevText = preview?.textContent?.trim() || '';

    // Time: short .text-muted that isn't the preview
    const allMuted = el.querySelectorAll('.text-muted');
    let time = '';
    for (const m of allMuted) {
      const t = m.textContent.trim();
      if (t && t.length < 20 && t !== prevText) time = t;
    }

    // Unread: green dot badge
    const dot = el.querySelector('span.badge.badge-pin');
    const unread = !!dot && getComputedStyle(dot).display !== 'none';

    return {
      name: h6?.textContent?.trim() || '',
      time,
      lastMsg: prevText.substring(0, 100),
      unread
    };
  }).filter(i => i.name);
}

/**
 * Read recent messages from the currently open LINE OA chat.
 * Run via browser evaluate on chat.line.biz after opening a chat.
 *
 * Returns: [{ time, text, isCustomer, hasImage }]
 * 
 * This script reads ALL visible messages in the messages panel,
 * up to a maximum of 50 recent messages.
 */
function() {
  const messages = document.querySelectorAll('.chat');
  const result = [];

  // Limit to last 50 messages to avoid token overflow
  const recentMessages = Array.from(messages).slice(-50);

  for (const msg of recentMessages) {
    // Skip if message has no content
    const textEl = msg.querySelector('.chat-body');
    if (!textEl) continue;

    // Extract time
    const timeEl = msg.querySelector('.text-muted.small');
    const time = timeEl?.textContent?.trim() || '';

    // Determine if this is a customer message (left side, no .chat-reverse)
    const isCustomer = !msg.classList.contains('chat-reverse');

    // Extract text content
    const text = textEl.textContent?.trim() || '';

    // Check for images
    const hasImage = !!msg.querySelector('img[alt="Photo"]');

    // Skip empty messages
    if (!text && !hasImage) continue;

    result.push({
      time,
      text: text.substring(0, 200), // Limit text length
      isCustomer,
      hasImage
    });
  }

  return result;
}

/**
 * Read unread customer messages from LINE OA chat.
 * Run via browser evaluate after opening a chat.
 *
 * Returns: { unreadMessages: [{ from, content, time, hasImage, imageSrc }], count }
 * Only includes customer messages (left-side white bubbles) after the unread divider.
 */
function() {
  // Find the unread divider by data-id attribute (most reliable method)
  const divider = document.querySelector('[data-id^="unread_"]');

  if (!divider) {
    return { unreadMessages: [], note: 'No unread divider found - all messages are read' };
  }

  // Get all chat bubbles after the divider
  const allChats = Array.from(document.querySelectorAll('.chat'));

  // Find the divider's position in DOM
  let chatsAfterDivider = [];
  let foundDivider = false;

  // Traverse DOM to find chats after the divider element
  allChats.forEach(chat => {
    // Check if we've passed the divider
    if (!foundDivider) {
      let el = chat.previousElementSibling;
      while (el) {
        if (el === divider || el.contains(divider)) {
          foundDivider = true;
          break;
        }
        el = el.previousElementSibling;
      }
    }

    // If we've found the divider, collect subsequent chats
    if (foundDivider) {
      chatsAfterDivider.push(chat);
    }
  });

  // Extract customer messages (white bubbles, no chat-reverse class)
  const unreadMessages = [];
  chatsAfterDivider.forEach(chat => {
    // Skip if it's from us (has chat-reverse class)
    if (chat.classList.contains('chat-reverse')) return;

    const content = chat.querySelector('.chat-content')?.innerText?.trim();
    const timeMatch = chat.innerText.match(/\d{2}:\d{2}/);
    const time = timeMatch ? timeMatch[0] : '';

    // Get sender name if available (usually in chat header)
    const nameEl = chat.querySelector('.chat-name, [class*="name"]');
    const from = nameEl?.textContent?.trim() || 'Customer';

    // Check for images
    const photoImg = chat.querySelector('img[alt="Photo"]');
    const hasImage = !!photoImg;
    let imageSrc = null;

    if (hasImage && photoImg) {
      imageSrc = photoImg.src;
    }

    if (content || hasImage) {
      unreadMessages.push({
        from,
        content: content ? content.split('\n')[0] : '', // Take first line only
        time,
        hasImage,
        imageSrc
      });
    }
  });

  return { unreadMessages, count: unreadMessages.length };
}

#!/usr/bin/env node
/**
 * LINE Official Account Setup Wizard
 * Run: node setup.js
 */

const fs = require('fs');
const path = require('path');
const readline = require('readline');
const { exec } = require('child_process');

const CONFIG_PATH = path.join(__dirname, '..', 'config.json');
const LINE_OA_URL = 'https://chat.line.biz/';

const rl = readline.createInterface({
  input: process.stdin,
  output: process.stdout
});

function question(prompt) {
  return new Promise(resolve => rl.question(prompt, resolve));
}

function openBrowser(url) {
  const platform = process.platform;
  const cmd = platform === 'darwin' ? 'open' :
              platform === 'win32' ? 'start' :
              'xdg-open';

  exec(`${cmd} "${url}"`, (err) => {
    if (err) {
      console.log(`⚠️  Could not auto-open browser. Please manually visit: ${url}`);
    }
  });
}

async function main() {
  console.log('\n🔧 LINE Official Account Setup\n');

  // Check if config already exists
  if (fs.existsSync(CONFIG_PATH)) {
    const existing = JSON.parse(fs.readFileSync(CONFIG_PATH, 'utf8'));
    console.log(`✅ Configuration already exists:`);
    console.log(`   ${existing.chatUrl}\n`);
    const overwrite = await question('Do you want to reconfigure? (y/N): ');
    if (overwrite.toLowerCase() !== 'y') {
      console.log('Setup cancelled.\n');
      rl.close();
      return;
    }
  }

  console.log('Opening LINE Official Account Manager in your browser...\n');
  openBrowser(LINE_OA_URL);

  console.log('📋 Instructions:');
  console.log('  1. Log in with your LINE Business ID');
  console.log('  2. Select your official account from the list');
  console.log('  3. Once on the chat interface, copy the full URL from the address bar');
  console.log('     (Should look like: https://chat.line.biz/Uebba4fb369276676ecc288d8b7181e49)\n');

  let chatUrl = '';
  let valid = false;

  while (!valid) {
    chatUrl = await question('Paste your LINE OA chat URL here: ');
    chatUrl = chatUrl.trim();

    if (!chatUrl) {
      console.log('❌ URL cannot be empty. Try again.\n');
      continue;
    }

    if (!chatUrl.startsWith('https://chat.line.biz/')) {
      console.log('❌ Invalid URL. Must start with https://chat.line.biz/\n');
      continue;
    }

    const parts = chatUrl.split('/');
    const accountId = parts[parts.length - 1];

    if (!accountId || accountId.length < 10) {
      console.log('❌ URL seems incomplete. Make sure to copy the full URL.\n');
      continue;
    }

    valid = true;
  }

  // Write config
  const config = { chatUrl };
  fs.writeFileSync(CONFIG_PATH, JSON.stringify(config, null, 2) + '\n', 'utf8');

  console.log('\n✅ Configuration saved!');
  console.log(`   ${chatUrl}`);
  console.log('\nYou can now use LINE OA commands with OpenClaw.\n');

  rl.close();
}

main().catch(err => {
  console.error('Error:', err);
  rl.close();
  process.exit(1);
});
